Document document = DocumentAnalyzer.builder()
    .add(sentenceAnnotator)
    .add(tokenAndPosAnnotator)
    .add(entityAnnotator)
    .add(new CorefAnnotator())
    .build()
    .analyze("Ada Lovelace advised Orion Labs. Lovelace saw its potential. She was right.");

List<Annotation<CorefMention>> chains = document.get(CorefAnnotator.CHAINS);
